def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opps = [o for o in opponents_status.values() if o.get('alive')]
    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids for immediate reaction
    prev_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Baseline from yesterday's observed bidding intensity
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        avg_prev_bid = sum(prev_bids) / float(len(prev_bids))
    else:
        highest_prev_bid = 0.0
        avg_prev_bid = 0.0

    # If my HP is critical, bid to avoid starvation
    hp_pressure = 0.0
    if my_hp <= 2.0:
        hp_pressure = 1.0
    elif my_hp <= 4.0:
        hp_pressure = 0.7
    elif my_hp <= 6.0:
        hp_pressure = 0.4
    else:
        hp_pressure = 0.2

    # Supply factor: higher supply reduces need to outbid
    # Normalize supply into [0,1]
    norm = (supply - float(MIN_SUPPLY)) / float(MAX_SUPPLY - MIN_SUPPLY)
    if norm < 0.0:
        norm = 0.0
    if norm > 1.0:
        norm = 1.0

    # Target bid: aim around yesterday average, but cap below typical max (~135)
    # Increase if yesterday highest bid was high.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        base = avg_prev_bid if avg_prev_bid > 0 else highest_prev_bid
        target = base + 5.0 * hp_pressure
    else:
        target = (avg_prev_bid if avg_prev_bid > 0 else DAILY_SALARY * 0.55)
        target = target + 8.0 * hp_pressure

    # Adjust for supply: if supply is low, bid more; if high, bid less
    target = target + (1.0 - norm) * 12.0

    # If I've already had no-water days, increase urgency
    if my_no_water_days >= 1:
        target = target + 10.0
    if my_no_water_days >= 2:
        target = target + 20.0

    # If opponent with 0 bid died yesterday, don't overreact; keep mid-high bid
    # (We already used yesterday stats; just ensure not too low.)
    min_floor = DAILY_SALARY * 0.45
    max_ceiling = 135.0  # observed max bids

    # Final clamp by budget and reasonable bounds
    target = max(min_floor * (1.0 if my_hp > 2 else 1.2), target)
    if target > max_ceiling:
        target = max_ceiling

    if target > my_budget:
        target = my_budget

    if target < 0.0:
        target = 0.0

    return float(target)

